 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Computer Languages Quiz</title>
     <style>
       :root {
         --bg: #f4f7fb;
         --panel: rgba(255, 255, 255, 0.88);
         --panel-border: rgba(148, 163, 184, 0.2);
         --text: #0f172a;
         --muted: #475569;
         --accent: #2563eb;
         --accent-soft: rgba(37, 99, 235, 0.12);
         --success: #059669;
         --shadow: 0 20px 45px rgba(15, 23, 42, 0.12);
         --radius: 24px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
           sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(59, 130, 246, 0.2), transparent 35%),
           radial-gradient(circle at top right, rgba(14, 165, 233, 0.16), transparent 30%),
           linear-gradient(180deg, #eef4ff 0%, var(--bg) 100%);
       }

       .page-shell {
         width: min(880px, calc(100% - 32px));
         margin: 48px auto;
       }

       .quiz-card {
         backdrop-filter: blur(16px);
         background: var(--panel);
         border: 1px solid var(--panel-border);
         border-radius: var(--radius);
         box-shadow: var(--shadow);
         overflow: hidden;
       }

       .hero {
         padding: 40px 40px 24px;
         background: linear-gradient(135deg, rgba(37, 99, 235, 0.1), rgba(14, 165, 233, 0.04));
         border-bottom: 1px solid rgba(148, 163, 184, 0.18);
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 8px;
         padding: 8px 12px;
         border-radius: 999px;
         background: rgba(255, 255, 255, 0.75);
         color: var(--accent);
         font-size: 0.8rem;
         font-weight: 700;
         letter-spacing: 0.04em;
         text-transform: uppercase;
       }

       h1 {
         margin: 18px 0 12px;
         font-size: clamp(2rem, 3vw, 3rem);
         line-height: 1.05;
       }

       .intro {
         margin: 0;
         max-width: 60ch;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.7;
       }

       form {
         padding: 28px;
       }

       .question-list {
         display: grid;
         gap: 20px;
       }

       .form-field {
         padding: 24px;
         background: #fff;
         border: 1px solid rgba(148, 163, 184, 0.18);
         border-radius: 20px;
         box-shadow: 0 12px 30px rgba(15, 23, 42, 0.05);
       }

       .question-meta {
         display: flex;
         align-items: center;
         gap: 12px;
         margin-bottom: 12px;
       }

       .question-number {
         display: grid;
         place-items: center;
         width: 36px;
         height: 36px;
         border-radius: 12px;
         background: var(--accent-soft);
         color: var(--accent);
         font-weight: 800;
       }

       .question-title {
         margin: 0;
         font-size: 1.1rem;
         line-height: 1.5;
       }

       .help-text {
         margin: 0 0 16px;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .option-grid {
         display: grid;
         gap: 12px;
       }

       .option {
         display: flex;
         align-items: flex-start;
         gap: 12px;
         padding: 14px 16px;
         border: 1px solid rgba(148, 163, 184, 0.2);
         border-radius: 16px;
         background: #f8fafc;
         cursor: pointer;
         transition: transform 160ms ease, border-color 160ms ease, background 160ms ease,
           box-shadow 160ms ease;
       }

       .option:hover {
         transform: translateY(-1px);
         border-color: rgba(37, 99, 235, 0.28);
         box-shadow: 0 10px 24px rgba(37, 99, 235, 0.08);
       }

       .option input {
         margin-top: 2px;
         width: 18px;
         height: 18px;
         accent-color: var(--accent);
       }

       .option-text {
         color: #1e293b;
         line-height: 1.5;
       }

       .actions {
         display: flex;
         flex-wrap: wrap;
         align-items: center;
         justify-content: space-between;
         gap: 16px;
         margin-top: 28px;
       }

       .hint {
         color: var(--muted);
         font-size: 0.95rem;
       }

       .submit-button {
         border: 0;
         border-radius: 14px;
         padding: 14px 22px;
         background: linear-gradient(135deg, #2563eb, #0ea5e9);
         color: #fff;
         font-weight: 700;
         font-size: 1rem;
         cursor: pointer;
         box-shadow: 0 14px 28px rgba(37, 99, 235, 0.24);
         transition: transform 160ms ease, box-shadow 160ms ease;
       }

       .submit-button:hover {
         transform: translateY(-1px);
         box-shadow: 0 18px 34px rgba(37, 99, 235, 0.28);
       }

       .results {
         margin-top: 24px;
         padding: 18px 20px;
         border-radius: 18px;
         background: rgba(5, 150, 105, 0.08);
         border: 1px solid rgba(5, 150, 105, 0.18);
       }

       .results strong {
         color: var(--success);
       }

       @media (max-width: 640px) {
         .page-shell {
           width: min(100% - 20px, 880px);
           margin: 20px auto;
         }

         .hero {
           padding: 28px 22px 20px;
         }

         form {
           padding: 18px;
         }

         .form-field {
           padding: 18px;
         }

         .actions {
           align-items: stretch;
         }

         .submit-button {
           width: 100%;
         }
       }
     </style>
   </head>
   <body>
     <div id="app"></div>

     <script>
       const quizData = [
         {
           id: "q1",
           title: "Which of these are primarily programming languages?",
           helpText: "Select every option that is commonly used to write application logic.",
           options: [
             { value: "javascript", label: "JavaScript" },
             { value: "python", label: "Python" },
             { value: "html", label: "HTML" },
             { value: "go", label: "Go" }
           ],
           correctAnswers: ["javascript", "python", "go"]
         },
         {
           id: "q2",
           title: "Which languages are commonly used for styling or describing web pages?",
           options: [
             { value: "css", label: "CSS" },
             { value: "html", label: "HTML" },
             { value: "rust", label: "Rust" },
             { value: "sql", label: "SQL" }
           ],
           correctAnswers: ["css", "html"]
         },
         {
           id: "q3",
           title: "Which of these are statically typed languages?",
           options: [
             { value: "typescript", label: "TypeScript" },
             { value: "java", label: "Java" },
             { value: "ruby", label: "Ruby" },
             { value: "csharp", label: "C#" }
           ],
           correctAnswers: ["typescript", "java", "csharp"]
         }
       ];

       const state = {
         answers: {},
         submitted: false,
         score: 0
       };

       const CheckboxOption = ({ questionId, option, checked }) => `
         <label class="option">
           <input type="checkbox" name="${questionId}" value="${option.value}" ${checked ? "checked" : ""} />
           <span class="option-text">${option.label}</span>
         </label>
       `;

       const QuestionCard = ({ question, index }) => `
         <div class="form-field">
           <div class="question-meta">
             <div class="question-number">${index + 1}</div>
             <h2 class="question-title">${question.title}</h2>
           </div>
           ${
             question.helpText
               ? `<p class="help-text" id="${question.id}-help">${question.helpText}</p>`
               : ""
           }
           <div class="option-grid" ${question.helpText ? `aria-describedby="${question.id}-help"` : ""}>
             ${question.options
               .map((option) =>
                 CheckboxOption({
                   questionId: question.id,
                   option,
                   checked: (state.answers[question.id] || []).includes(option.value)
                 })
               )
               .join("")}
           </div>
         </div>
       `;

       const Results = () => `
         <div class="results" role="status" aria-live="polite">
           <strong>Submitted.</strong> You scored ${state.score} out of ${quizData.length}.
         </div>
       `;

       const SubmitButton = () => `
         <button class="submit-button" type="submit">Submit Quiz</button>
       `;

       const QuizForm = () => `
         <form id="quiz-form">
           <div class="question-list">
             ${quizData.map((question, index) => QuestionCard({ question, index })).join("")}
           </div>
           <div class="actions">
             <div class="hint">Each question supports multiple selections.</div>
             ${SubmitButton()}
           </div>
           ${state.submitted ? Results() : ""}
         </form>
       `;

       const App = () => `
         <main class="page-shell">
           <section class="quiz-card">
             <header class="hero">
               <div class="eyebrow">Interactive quiz</div>
               <h1>Computer Languages Knowledge Check</h1>
               <p class="intro">
                 Explore three quick questions about programming and web languages in a polished,
                 product-style quiz experience.
               </p>
             </header>
             ${QuizForm()}
           </section>
         </main>
       `;

       function calculateScore() {
         return quizData.reduce((score, question) => {
           const selected = [...(state.answers[question.id] || [])].sort();
           const correct = [...question.correctAnswers].sort();
           return JSON.stringify(selected) === JSON.stringify(correct) ? score + 1 : score;
         }, 0);
       }

       function render() {
         document.getElementById("app").innerHTML = App();
         bindEvents();
       }

       function bindEvents() {
         const form = document.getElementById("quiz-form");

         form.querySelectorAll('input[type="checkbox"]').forEach((input) => {
           input.addEventListener("change", (event) => {
             const { name, value, checked } = event.target;
             const currentSelections = new Set(state.answers[name] || []);

             if (checked) {
               currentSelections.add(value);
             } else {
               currentSelections.delete(value);
             }

             state.answers[name] = [...currentSelections];
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;
           state.score = calculateScore();
           render();
         });
       }

       render();
     </script>
   </body>
 </html>
